theorem nb_walk_isPath_of_girth {V : Type*} (G : SimpleGraph V) {r : ℕ}
    (hg : ∀ (v : V) (c : G.Walk v v), c.IsCycle → 2 * r + 1 < c.length) :
    ∀ {x y : V} (w : G.Walk x y), IsNonBacktracking w → w.length ≤ r → w.IsPath

theorem mem_nbWalksFrom [Fintype V] [DecidableEq V] [DecidableRel G.Adj] {x : V} {k : ℕ}
