theorem mem_adjoin_simple_sq {F : Type*} [Field F] {E : Type*} [Field E] [Algebra F E] {y : E}
    {a : F} (hy : y ^ 2 = algebraMap F E a) {z : E} :
    z ∈ IntermediateField.adjoin F {y}
      ↔ ∃ u v : F, z = algebraMap F E u + algebraMap F E v * y

theorem multiquadraticRelations_ycoord {L : Type*} [Field L] [NeZero (2 : L)] {E : Type*}
    [Field E] [DecidableEq E] [Algebra L E] {s' : Finset E} {y : E} (hys : y ∉ s') {c : E → L}
    (hs : ∀ x ∈ insert y s', x ^ 2 = algebraMap L E (c x)) (hc : ∀ x ∈ insert y s', c x ≠ 0) :
    (∃ ε : E → ZMod 2, ε ∈ multiquadraticRelations (insert y s') c ∧ ε y = 1)
      ↔ IsSquare (algebraMap L (↥(IntermediateField.adjoin L (s' : Set E))) (c y))

theorem TwoIndependent.sqrt_injective {n : ℕ} {v : Fin n → ℚ} (hv : TwoIndependent v)
    {K : Type*} [Field K] [Algebra ℚ K] {x : Fin n → K}
    (hx : ∀ i, x i ^ 2 = algebraMap ℚ K (v i)) : Function.Injective x

lemma finrank_adjoin_range_eq_two_pow {n : ℕ}
    (hindep : TwoIndependent (fun i : Fin n ↦ (cSeq a ((i : ℕ) + 1) : ℚ)))
    {x : Fin n → ↥(splittingField a n)}
    (hx : ∀ i, x i ^ 2 = algebraMap ℚ ↥(splittingField a n) (cSeq a ((i : ℕ) + 1) : ℚ)) :
    Module.finrank ℚ (IntermediateField.adjoin ℚ (Set.range x)) = 2 ^ n

lemma finrank_eq_of_nonempty_mulEquiv {n : ℕ}
    (hiso : Nonempty (GaloisGroup a n ≃* WreathPower n)) :
    Module.finrank ℚ ↥(splittingField a n) = 2 ^ (2 ^ n - 1)

lemma nonempty_mulEquiv_of_finrank_eq {n : ℕ}
    (hmax : Module.finrank ℚ ↥(splittingField a n) = 2 ^ (2 ^ n - 1)) :
    Nonempty (GaloisGroup a n ≃* WreathPower n)

lemma isHom_cast
    {B} {instB : QuasiBorelSpace B}
    {C} {instC : QuasiBorelSpace C}
    {eq : B = C} (heq : ∀ (φ : ℝ → B), IsHom φ ↔ IsHom fun x ↦ cast eq (φ x))
    (f : A → B)
    : IsHom (fun x ↦ cast eq (f x)) ↔ IsHom f

lemma isHom_def
    {A : Type*} {_ : QuasiBorelSpace A}
    {B : Type*} {_ : QuasiBorelSpace B}
    (f : A → B)
    : IsHom f ↔ (∀⦃φ : ℝ → A⦄, IsHom φ → IsHom fun x ↦ f (φ x))
